using System;
using UnityEngine;

/// <summary>
/// A cosmetic firework projectile: travels from a launch point to a target and
/// fires a callback the moment it arrives, then cleans itself up. It carries only a
/// trail (no model, by design) — the impact effect is spawned by the callback.
/// Movement is frame-rate independent.
/// </summary>
public sealed class FireworkProjectile : MonoBehaviour
{
    private Transform _target;
    private Vector3 _lastKnownTargetPos;
    private float _speed;
    private float _arriveDistance;
    private float _trailFadeAfterArrive;
    private Action _onArrive;
    private GameObject _trail;
    private bool _arrived;

    /// <summary>
    /// Sends this projectile toward <paramref name="target"/>. On arrival it invokes
    /// <paramref name="onArrive"/> once and destroys itself. If a trail prefab is
    /// given it is spawned as a child and, on impact, detached so it can finish
    /// fading instead of being cut off.
    /// </summary>
    public void Launch(
        Vector3 start,
        Transform target,
        GameObject trailPrefab,
        float speed,
        float arriveDistance,
        float trailFadeAfterArrive,
        float sizeMultiplier,
        Action onArrive)
    {
        transform.position = start;
        _target = target;
        _lastKnownTargetPos = target != null ? target.position : start;
        _speed = Mathf.Max(0.01f, speed);
        _arriveDistance = Mathf.Max(0.01f, arriveDistance);
        _trailFadeAfterArrive = Mathf.Max(0f, trailFadeAfterArrive);
        _onArrive = onArrive;

        if (trailPrefab != null)
        {
            _trail = Instantiate(trailPrefab, transform.position, transform.rotation, transform);
            _trail.transform.localPosition = Vector3.zero;
            ApplySizeMultiplier(_trail, sizeMultiplier);
        }
    }

    // Bigger sparks without editing the shared CFXR asset: scale every child particle
    // system's start size. startSizeMultiplier is a plain float layered on top of the
    // authored size, so this is non-destructive.
    private static void ApplySizeMultiplier(GameObject trail, float multiplier)
    {
        if (trail == null || multiplier <= 0f || Mathf.Approximately(multiplier, 1f))
        {
            return;
        }

        foreach (ParticleSystem ps in
            trail.GetComponentsInChildren<ParticleSystem>(true))
        {
            ParticleSystem.MainModule main = ps.main;
            main.startSizeMultiplier *= multiplier;
        }
    }

    private void Update()
    {
        if (_arrived)
        {
            return;
        }

        // The target can be destroyed mid-flight (e.g. a shop swap), so fall back to
        // its last known position — the projectile still lands and its effect resolves.
        Vector3 targetPos = _target != null ? _target.position : _lastKnownTargetPos;
        _lastKnownTargetPos = targetPos;

        Vector3 toTarget = targetPos - transform.position;
        float distance = toTarget.magnitude;
        float step = _speed * Time.deltaTime;

        if (distance <= _arriveDistance || distance <= step)
        {
            transform.position = targetPos;
            Arrive();
            return;
        }

        transform.position += toTarget / distance * step;
        transform.rotation = Quaternion.LookRotation(toTarget);
    }

    private void Arrive()
    {
        _arrived = true;
        _onArrive?.Invoke();

        if (_trail != null)
        {
            // Detach so a TrailRenderer / particle system can play out its tail
            // rather than vanishing the instant the projectile is destroyed.
            _trail.transform.SetParent(null, true);
            Destroy(_trail, _trailFadeAfterArrive);
        }

        Destroy(gameObject);
    }
}
